      hu: ["Hosszúság: 230 km.", "Vízgyűjtő terület: 14.000 km².", "Árterek szélessége: akár 1 km.", "Halászati termelés: 5.000 tonna/év.", "Hőforrások: Sempaya közelében.", "Olajkutatás kezdete: 2010."],
      ro: ["Lungime: 230 km.", "Debit mediu: 100 m³/s.", "Bazin hidrografic: 14.000 km².", "Captură anuală de pește: 5.000 tone.", "Graniță naturală cu Republica Democrată Congo.", "Izvoare termale active."],
      en: ["Length: 230 km.", "Discharge: 100 m³/s (mean).", "Catchment area: 14,000 km².", "Fish catch: over 5,000 tons/year.", "Part of Semliki Wildlife Reserve.", "Oil exploration began in 2010."],
      es: ["Longitud: 230 km.", "Cuenca: 14.000 km².", "Caudal medio: 100 m³/s.", "Captura anual de pescado: 5.000 toneladas.", "El curso inferior forma la frontera con la RDC.", "Hogar de más de 400 especies de aves."],
      pt: ["Comprimento: 230 km.", "Bacia: 14.000 km².", "Caudal médio: 100 m³/s.", "Captura anual de peixe: 5.000 toneladas.", "O curso inferior forma a fronteira com a RDC.", "Lar de mais de 400 espécies de aves."],
      fr: ["Longueur : 230 km.", "Bassin versant : 14 000 km².", "Débit moyen : 100 m³/s.", "Prise annuelle de poissons : 5 000 tonnes.", "Le cours inférieur forme la frontière avec la RDC.", "Abrite plus de 400 espèces d'oiseaux."],
